text:
{
  "units": [
    {
      "issue": "核对虚构情景中截至2023-08-01最终诉请时，A、B、C各项可请求余额及乙、丁、戊、庚、己、辛各自的责任范围；核心依赖为保证状态影响付款抵充，付款后的债务范围再影响第三人承接及原保证责任。此为待核验判断单元，不是法院实际判断。",
      "decisive_facts": [
        {
          "id": "F01",
          "spans": ["normalized_text:导言", "S12", "S14"],
          "fact": "全部交易与程序记录均为显著标注的虚构题设。除单方法律主张外，相关事实无争议；结算不计2023-08-01当日利息。最终核对需结合16:10追加请求，不能只读取较早的诉请表述。"
        },
        {
          "id": "F02",
          "spans": ["S01", "S02"],
          "fact": "A成立于2022-03-11，资金为套取的银行信贷资金；票面160000元，实际交付143123.00元。乙事先不知来源，约定利率6%。此前返还20307.00元，双方约定如合同无效，该款全部冲抵返还财产；不请求无效后的其他赔偿。丁提供连带保证。同交易号收据不是另一笔交付。"
        },
        {
          "id": "F03",
          "spans": ["S03", "S04", "S05"],
          "fact": "B以合法自有资金出借，2022-01-12实际交付并成立、起息；票面199581.00元包含预扣利息12551.00元，实际到账187030.00元。约定年利率13.200%，成立时一年期LPR题设值3.70%。三个归档日为2022-07-06、2022-10-17、2023-01-09，纸面本金分别为212212.02元、220116.77元、226803.49元，均无新增交付。"
        },
        {
          "id": "F04",
          "spans": ["S04", "S06"],
          "fact": "B结算协议允许逐次结息记账，不构成债务更新；沿用原利率与原成立时LPR，采用实际自然日/365，中间不取分。原到期日2023-01-12，甲乙另展期至2023-06-30，戊、庚均未书面同意展期，但同意原结息机制。"
        },
        {
          "id": "F05",
          "spans": ["S06"],
          "fact": "戊、庚在同一保证文件上签名，各自向甲覆盖全部B债务，另约定内部相互追偿及各50%的分担份额。保证期间均写为直至本息还清。甲针对戊的诉讼2023-07-05受理，给付请求2023-07-07送达，2023-07-09撤诉；甲另于2023-07-06向庚提出完整给付请求且实际到达。"
        },
        {
          "id": "F06",
          "spans": ["S07", "S08", "S09"],
          "fact": "C于2019-02-07实际交付227790.00元并成立、起息，到期日2022-12-15，借期及逾期约定年利率均为23.50%。各次起诉时一年期LPR题设值均为3.25%。甲明确请求分段适用利率保护规则。合理实现债权费用1680元于2019-04-17发生并到期。"
        },
        {
          "id": "F07",
          "spans": ["S07", "S08", "S09", "S11"],
          "fact": "C按未偿本金、实际自然日/365单利计算，付款当日不再对被偿本金计息，未付利息不生息。S08列有七笔已结算付款；原合同约定费用、依法可请求利息、本金的顺序，双方仅对T-02另约定本金优先。其他还本金备注为乙单方记载。T-01截图与收据对应同一交易，X-01未执行且未入账。"
        },
        {
          "id": "F08",
          "spans": ["S10"],
          "fact": "己的保证于2022-02-07另行成立，正文以乙不能履行、无力偿还为承担条件，未另定保证期间。甲2023-06-08起诉乙，2023-06-12撤诉，2023-06-14重新起诉并获受理，截日尚未审判。己2023-06-25仅确认收到催告，并明确不确认付款义务；无新保证承诺。乙有可执行财产，无题设列明的先诉抗辩例外，己未放弃该抗辩。"
        },
        {
          "id": "F09",
          "spans": ["S06", "S10", "S13"],
          "fact": "SP-01于2023-08-01 09:20实际到账25000.00元，仅清偿B、C，不清偿A；未在B、C间具体指定。双方约定：两债务均到期且有同等资信的全额保证时，先清偿付款日依法可强制请求年利率较高者，其他情形依法处理。两债务无其他担保，相关保证人在依法存续范围内的履行能力与价值无争议。"
        },
        {
          "id": "F10",
          "spans": ["S14"],
          "fact": "13:40甲乙辛三方签署文书，正文约定SP-01结算后的全部C债务由辛独自履行，甲不再向乙请求，乙不再负该部分付款义务。己未签署、未另给书面同意，也无新保证文件；无新增交付，原交付日、利率、到期日未另改动。"
        },
        {
          "id": "F11",
          "spans": ["S12", "S14"],
          "fact": "金额按各输出分项最终取分后合计。S14实际处分对象为全部C剩余债务；其中涉及50%时如何取分的通用条款，未单独设定本次转移比例。SP-01后无其他付款。"
        },
        {
          "id": "F12",
          "spans": ["S06", "S11", "S12"],
          "fact": "庚、戊的免责意见，己关于旧借款决定保证适用规则的意见，甲关于文书标题决定辛责任的意见，以及乙关于点击付款及后来文书改变先前抵充的意见，均属于待核验主张，不作为已认可法律结论。"
        }
      ],
      "support_spans": [
        {
          "kind": "material",
          "span_ids": ["S01", "S02"],
          "supports": ["F02"],
          "basis": "资金来源、实际交付、既有返还及附条件清算约定。"
        },
        {
          "kind": "material",
          "span_ids": ["S03", "S04", "S05", "S06"],
          "supports": ["F03", "F04", "F05"],
          "basis": "B原始交付与结息资料、展期、保证原文及分别行权记录。"
        },
        {
          "kind": "material",
          "span_ids": ["S07", "S08", "S09", "S10", "S11"],
          "supports": ["F06", "F07", "F08"],
          "basis": "C原合同、逐笔付款、顺序例外、执行状态与保证程序记录。"
        },
        {
          "kind": "material",
          "span_ids": ["normalized_text:导言", "S06", "S12", "S13", "S14"],
          "supports": ["F01", "F09", "F10", "F11", "F12"],
          "basis": "虚构声明、付款与签约先后、第三人义务正文、诉请和单方主张的性质。"
        },
        {
          "kind": "authority",
          "source_id": "civil-code-2020",
          "provisions": ["157", "560", "561", "670", "679", "682", "686", "687", "688", "691", "692", "693", "695", "552", "697", "1260"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html",
          "basis": "材料所附民法典摘录涉及返还、抵充、实际本金、保证及债务主体变动；本次未外部复核网页。"
        },
        {
          "kind": "authority",
          "source_id": "lending-2020-12",
          "provisions": ["13", "25", "26", "27", "28", "31"],
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html",
          "basis": "材料所附摘录涉及转贷效力、利率与结息限制、逾期利息及旧合同利息过渡。"
        },
        {
          "kind": "authority",
          "source_id": "lending-2015",
          "provisions": ["26"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/15146.html",
          "basis": "材料所附旧版第26条提供C过渡日前利息保护标准。"
        },
        {
          "kind": "authority",
          "source_id": "guarantee-2020",
          "provisions": ["13", "25", "29", "31", "32", "34", "36"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/282721.html",
          "basis": "材料所附摘录涉及保证类型、内部追偿、分别行权、撤诉、期间约定及第三人承诺解释。"
        }
      ],
      "dependencies": {
        "nodes": [
          {
            "id": "D01",
            "judgment": "建立适用时间和事件边界，区分C旧借款、2022年新保证、09:20付款及13:40主体变动。",
            "depends_on": [],
            "fact_refs": ["F01", "F03", "F06", "F08", "F09", "F10"],
            "rule_refs": ["civil-code-2020:1260", "lending-2020-12:31"],
            "basis": "合同成立、保证成立、付款与主体变动不是同一法律事实，不共用一个时间标签。"
          },
          {
            "id": "D02",
            "judgment": "识别实际交付、实际清偿和重复凭证，形成唯一交易账本。",
            "depends_on": [],
            "fact_refs": ["F02", "F03", "F07", "F09"],
            "rule_refs": ["civil-code-2020:670", "civil-code-2020:679", "lending-2020-12:26"],
            "basis": "同交易号重复载体不产生新增款项；未执行指令与已结算付款分别记录。"
          },
          {
            "id": "D03",
            "judgment": "核验A效力、实际财产返还余额及丁是否承担所请求的合同保证责任。",
            "depends_on": ["D01", "D02"],
            "fact_refs": ["F02"],
            "rule_refs": ["lending-2020-12:13", "civil-code-2020:157", "civil-code-2020:682"],
            "basis": "资金来源决定效力审查，清算协议限定冲抵口径；合同保证责任与无效后的过错赔偿须分开。"
          },
          {
            "id": "D04",
            "judgment": "重建B合法本金与逐次结息，独立比较逐期可计入数额和原始本金全期上限，再核对截日付款前余额。",
            "depends_on": ["D01", "D02"],
            "fact_refs": ["F03", "F04"],
            "rule_refs": ["civil-code-2020:670", "lending-2020-12:25", "lending-2020-12:26", "lending-2020-12:27", "lending-2020-12:28"],
            "basis": "纸面归档额不等于新增交付或当然可保护本金；结息限制与整体限制必须分别核对。"
          },
          {
            "id": "D05",
            "judgment": "确定C分段合法利率，按付款日期和有效顺序逐笔更新费用、利息、本金，形成付款前余额及付款日合法年利率。",
            "depends_on": ["D01", "D02"],
            "fact_refs": ["F06", "F07"],
            "rule_refs": ["lending-2015:26", "lending-2020-12:25", "lending-2020-12:28", "lending-2020-12:31", "civil-code-2020:561"],
            "basis": "旧法阶段的清偿顺序已有原合同与补充协议支持，不追溯以第561条代替；T-02与其他付款的约定不同。"
          },
          {
            "id": "D06",
            "judgment": "分别核验戊、庚的保证类型、期间、期间内行权及内部追偿减责前提，确定付款时B的担保覆盖范围。",
            "depends_on": ["D01", "D04"],
            "fact_refs": ["F04", "F05", "F12"],
            "rule_refs": ["civil-code-2020:688", "civil-code-2020:691", "civil-code-2020:692", "civil-code-2020:693", "civil-code-2020:695", "guarantee-2020:13", "guarantee-2020:25", "guarantee-2020:29", "guarantee-2020:31", "guarantee-2020:32"],
            "basis": "戊的送达与撤诉、庚的直接催告分别审查；内部各半不直接替代对外全部覆盖条款。"
          },
          {
            "id": "D07",
            "judgment": "核验己在09:20时的保证类型、期间与再诉效果，分开记录保证存续和即时请求障碍。",
            "depends_on": ["D01", "D05"],
            "fact_refs": ["F08", "F12"],
            "rule_refs": ["civil-code-2020:686", "civil-code-2020:687", "civil-code-2020:691", "civil-code-2020:692", "civil-code-2020:693", "guarantee-2020:25", "guarantee-2020:31", "guarantee-2020:34"],
            "basis": "期间内再诉、先诉抗辩与仅确认收件具有不同法律作用，不能合并为一个失效标签。"
          },
          {
            "id": "D08",
            "judgment": "按SP-01到账时状态判断约定的适用条件，选择B或C，再在所选债务内部抵充并更新余额。",
            "depends_on": ["D04", "D05", "D06", "D07"],
            "fact_refs": ["F09"],
            "rule_refs": ["civil-code-2020:560", "civil-code-2020:561", "civil-code-2020:687"],
            "basis": "担保覆盖与价值影响约定是否适用；约定要求比较依法可请求利率，而非被限制的名义利率。"
          },
          {
            "id": "D09",
            "judgment": "按S14正文识别第三人承接的法律性质、范围和生效后的责任主体，并核验己对该部分债务的保证后果。",
            "depends_on": ["D01", "D07", "D08"],
            "fact_refs": ["F10", "F11"],
            "rule_refs": ["civil-code-2020:552", "civil-code-2020:697", "guarantee-2020:36"],
            "basis": "正文包含辛独自履行及乙退出的意思表示；范围以先前付款后的余额确定，不能由标题或通用50%取分条款替代。",
            "support_gap": "现有摘录未包含债务转移的一般成立规则；见answerability中的规范缺口。"
          },
          {
            "id": "D10",
            "judgment": "按最终诉请逐主体列明责任性质、范围和可立即请求金额，并形成不重复计算的债权总额。",
            "depends_on": ["D03", "D04", "D05", "D06", "D07", "D08", "D09"],
            "fact_refs": ["F01", "F11", "F12"],
            "rule_refs": ["civil-code-2020:682", "civil-code-2020:687", "civil-code-2020:688", "civil-code-2020:697"],
            "basis": "保证人的责任范围不是新增独立债权；需区分付款时担保状态与最终诉请时责任状态，并按约定最终取分。"
          }
        ],
        "terminal_node": "D10",
        "required_interactions": [
          "D06与D07确定付款时担保状态，影响D08的B/C抵充。",
          "D04与D05确定余额及合法利率，影响D08的约定条件与清偿结果。",
          "D08形成的剩余债务范围影响D09的主体变动及保证后果。",
          "D09只影响其后责任，不反向改写D08已经发生的付款抵充。"
        ]
      },
      "answerability": {
        "status": "partial",
        "fact_coverage": "本主单元所需的交付、付款、利率参数、保证条款、行权记录及事件先后均有明确题设定位；未发现必须以隐藏裁判补足的事实。",
        "supported_scope": "可以提取主判断单元及依赖图，A、B、C余额计算与付款时保证状态具有材料依据。",
        "blocking_gaps": [
          {
            "node": "D09",
            "type": "normative_excerpt_gap",
            "description": "规则集中已有债务加入、第三人承诺及债务转移对保证责任影响的摘录，但缺少债务转移的一般成立规则。就要求完整随题法源的闭卷训练，应补入并核验民法典第551条的适用版本与原文。",
            "effect": "不是认定S14无效，也不是制造事实争议；在规范输入完整性确认前，不冻结包含全部主体责任的最终参考答案。"
          }
        ],
        "numeric_status": "P1未计算最终金额，未完成十进制定点独立复算。",
        "next_stage_condition": "补齐必要规范摘录后再进行题面充分性审查、答案生成及独立核验；不得将本依赖图直接标为已验收答案。"
      }
    }
  ],
  "rejected_units": [
    {
      "issue": "提取原案法院对本情景的认定、理由或裁判金额",
      "reason": "材料明确为新构造情景，不存在可据以提取的本情景法院实际判断。",
      "support_spans": ["normalized_text:导言", "material_pack.source.kind"]
    },
    {
      "issue": "计算丁等主体因保证无效产生的过错赔偿",
      "reason": "诉请明确排除该项目，也未提供足以确定过错比例与损失的事实。",
      "support_spans": ["S02", "S12"]
    },
    {
      "issue": "将S14认定为仅承接50%的既定事实",
      "reason": "实体义务条款写明全部剩余C债务；通用取分条款不能生成未约定的半数承接事实。",
      "support_spans": ["S14"]
    },
    {
      "issue": "将诉讼追加获准等同于实体责任已被法院确认",
      "reason": "程序回执只支持追加请求与被告的程序事实，不能替代实体义务判断；题设亦不要求判断合并程序。",
      "support_spans": ["S14"]
    }
  ],
  "limitations": [
    "事实仅在显著虚构的题设内部成立，不对外宣称为真实证据、真实裁判或专家审核结果。",
    "法规URL、版本和哈希来自提供的数据，本次未联网核验其原文、定位或版本完整性；effective_to为null不证明现行有效。",
    "两组LPR数值是题设参数，不是对现实历史报价的独立核验。",
    "source中的机制说明、历史轮次、数值参考未变等研究元数据，不作为实体责任或金额结论的证据。",
    "未读取未提供的外部参考文件、历史运行记录或工程答案；未开展出题、种子选择、盲答或经验难度评估。",
    "本次仅形成公开可审计的依赖结构；不输出最终金额答案，不据结构复杂度宣称命中任何实测难度区间。"
  ]
}
